var i=`0684-caldo-de-chabeu`;var t=`world-0684`;var a=`GW`;var s=`western-africa`;var o=4;var r=58;var l={en:`Caldo de Chabéu`,ua:`Кальду де шабеу`};var d={en:`Caldo de Chabéu is a Guinea-Bissau classic prepared with fish (unspecified), yellow onion, palm nut concentrate, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Кальду де шабеу, страва кухні країни Гвінея-Бісау зі складниками: риба (невизначений вид), жовта цибуля, концентрат пальмових плодів, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`fish-unspecified`,650,`g`],[`yellow-onion`,160,`g`],[`palm-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 42 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 42 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:42,i:[[`palm-nut-concentrate`,220,`g`],[`water`,760,`ml`],[`tomato`,240,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,18,`g`]]}];var g={slug:i,id:t,country:`GW`,region:s,servings:4,minutes:58,title:l,text:d,steps:u};export{a as country,g as default,t as id,r as minutes,s as region,o as servings,i as slug,u as steps,d as text,l as title};